// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1e30);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // sanity on the reference behaviour: funds are recorded
        assertTrue(c.getBalance(actor) >= amount);

        vm.prank(actor);
        bool ok;
        try c.withdrawBalance() { ok = true; } catch { ok = false; }

        // GENERAL RULE: after a successful withdrawal, the caller's recorded
        // balance must be zero. The mutant never zeroes it, so this fails.
        assertTrue(ok && c.getBalance(actor) == 0);
    }
}
